+import type { EventOf, SessionEvent } from '../types.ts';
+
+// The slop guard reads a run's own changes and names shortcuts that make the work look done: tests deleted,
+// weakened or skipped, silenced checks, swallowed errors, type escapes and stubs. Pure: it reads lines, never
+// the model's words. Findings never refuse a claim; the loop reminds once and the evidence carries the rest.
+export type SlopRule = 'test-deleted' | 'test-weakened' | 'test-skipped' | 'suppression' | 'swallowed-error' | 'type-escape' | 'stub';
+export type FileChange = { path: string; added: string[]; removed: string[]; deleted: boolean };
+export type SlopFinding = { rule: SlopRule; path: string; detail?: string };
+
+export const flagOf = (f: SlopFinding) => `${f.rule} ${f.path}${f.detail ? `: ${f.detail}` : ''}`;
+
+const CODE = /\.(ts|tsx|mts|cts|js|jsx|mjs|cjs|py|go|rs|rb|java|kt|kts|cs|c|h|cc|cpp|hpp|swift|php|scala|sh|bash|zsh|lua|ex|exs|dart|vue|svelte|sql|clj|hs|ml|nim|zig)$/i;
+
+export const isTestPath = (path: string) =>
+  /(^|\/)(tests?|__tests__|spec)\//.test(path) || /\.(test|spec)\.[a-z]+$/i.test(path) || /_test\.go$/i.test(path) || /(^|\/)test_.*\.py$/i.test(path) || /_test\.py$/i.test(path);
+
+const isAssertion = (l: string) =>
+  /\bexpect\s*\(/.test(l) || /^\s*assert\b/.test(l) || /\bassert\.\w+\(/.test(l) || /\b(t|b|s)\.(Error|Errorf|Fatal|Fatalf|Fail|FailNow)\b/.test(l) || /\b(require|assert)\.\w+\(/.test(l) || /\.should\b/.test(l);
+
+const isSuppression = (l: string) =>
+  /@ts-(ignore|nocheck|expect-error)\b/.test(l) ||
+  /\b(eslint-disable|prettier-ignore|biome-ignore|oxlint-disable|deno-lint-ignore|nolint)\b/.test(l) ||
+  /#\s*(type:\s*ignore|noqa\b|pylint:\s*disable|mypy:\s*ignore)/.test(l) ||
+  /#\[(allow|expect)\(/.test(l);
+
+// A comment that talks about slop is not slop. `#[...]` is Rust and stays code.
+const commentOnly = (l: string) => /^(\/\/|\/\*|\*|#(?![![]))/.test(l);
+
+const isSkip = (l: string) =>
+  /\.(skip|todo)\s*\(/.test(l) ||
+  /\bt\.Skip\w*\(/.test(l) ||
+  /^@(pytest\.mark\.)?skip\b/.test(l) ||
+  /^\s*x(it|describe|test)\s*\(/.test(l) ||
+  /^#\[ignore\]/.test(l);
+
+// An empty catch or an `except: pass` throws away the error. A handler that logs or rethrows does not.
+const isSwallowed = (l: string) =>
+  /\bcatch\s*(\([^)]*\))?\s*\{\s*\}/.test(l) ||
+  /^except\b[^:]*:\s*(pass|\.\.\.)\s*$/.test(l) ||
+  /\.catch\s*\(\s*(\(\s*\w*\s*\)|\w+)\s*=>\s*\{\s*\}\s*\)/.test(l);
+
+const isTypeEscape = (l: string) => /\bas\s+any\b/.test(l) || /:\s*any\b/.test(l) || /<any>/.test(l) || /,\s*any\s*>/.test(l);
+
+const isStub = (l: string) => /not[ _-]?implemented\b|\bNotImplementedError\b|unimplemented!\s*\(|todo!\s*\(|TODO:?\s*implement\b/i.test(l);
+
+function ruleFor(line: string, test: boolean): SlopRule | undefined {
+  const l = line.trim();
+  if (!l) return undefined;
+  if (isSuppression(l)) return 'suppression';
+  if (commentOnly(l)) return undefined;
+  if (test && isSkip(l)) return 'test-skipped';
+  if (isSwallowed(l)) return 'swallowed-error';
+  if (isTypeEscape(l)) return 'type-escape';
+  if (isStub(l)) return 'stub';
+  return undefined;
