+      continue;
+    }
+    if (!cur) continue;
+    if (line.startsWith('deleted file mode ')) cur.deleted = true;
+    else if (line.startsWith('--- ')) cur.path = stripAB(line.slice(4)) ?? cur.path;
+    else if (line.startsWith('+++ ')) {
+      const p = stripAB(line.slice(4));
+      if (p) cur.path = p;
+      else cur.deleted = true;
+    } else if (line.startsWith('+')) cur.added.push(line.slice(1));
+    else if (line.startsWith('-')) cur.removed.push(line.slice(1));
+  }
