+export function changesFromCalls(events: SessionEvent[]): FileChange[] {
+  const intents = new Map<string, EventOf<'tool_intent'>>();
+  const out: FileChange[] = [];
+  for (const e of events) {
+    if (e.kind === 'request') intents.clear();
+    if (e.kind === 'tool_intent') intents.set(e.callId, e);
+    if (e.kind !== 'tool_result' || e.status !== 'completed') continue;
+    const intent = intents.get(e.callId);
+    const path = String(intent?.input.path ?? '');
+    if (!intent || !path) continue;
+    if (intent.tool === 'write' && typeof intent.input.content === 'string')
+      out.push({ path, added: linesOf(intent.input.content), removed: [], deleted: false });
+    else if (intent.tool === 'edit' && Array.isArray(intent.input.edits)) {
+      const added: string[] = [];
+      const removed: string[] = [];
+      for (const x of intent.input.edits as { old_text?: unknown; new_text?: unknown }[]) {
+        removed.push(...linesOf(String(x.old_text ?? '')));
+        added.push(...linesOf(String(x.new_text ?? '')));
+      }
+      out.push({ path, added, removed, deleted: false });
+    }
+  }
+  return out;
+}
