+  { rule: 'swallowed-error', re: /\bcatch\s*(?:\([^)]*\))?\s*\{\s*\}/ },
+  { rule: 'swallowed-error', re: /\bexcept\b[^:]*:\s*(?:pass|\.\.\.)\s*$/ },
+  { rule: 'swallowed-error', re: /\.catch\(\s*(?:\([^)]*\)|\w+)?\s*=>\s*\{\s*\}\s*\)/ },
+  { rule: 'type-escape', re: /\bas\s+any\b|<any>|:\s*any\b/ },
