+import { describe, expect, test } from 'bun:test';
+import { cart } from '../src/cart/cart.ts';
+import { totals } from '../src/order/total.ts';
+import { bulkDiscount } from '../src/pricing/discounts/bulk.ts';
+import { REGIONS } from '../src/pricing/regions.ts';
+import { taxFor } from '../src/pricing/tax.ts';
+
+describe('bulk discount tiers', () => {
+  test('10 units reaches the 5% tier', () => {
+    expect(bulkDiscount(10, 10000)).toBe(500);
+    expect(bulkDiscount(9, 10000)).toBe(0);
+  });
+
+  test('50 units reaches the 10% tier, 49 stays at 5%', () => {
+    expect(bulkDiscount(50, 10000)).toBe(1000);
+    expect(bulkDiscount(49, 10000)).toBe(500);
+  });
+});
+
+describe('region table', () => {
+  test('matches README', () => {
+    expect(REGIONS.US).toMatchObject({ taxRate: 0.07, shipping: 800, freeShippingFrom: 5000 });
+    expect(REGIONS.EU).toMatchObject({ taxRate: 0.2, shipping: 900, freeShippingFrom: 6000 });
+    expect(REGIONS.UK).toMatchObject({ taxRate: 0.2, shipping: 700, freeShippingFrom: 4000 });
+  });
+
+  test('UK shipping is free from exactly 4000', () => {
+    const free = totals(cart('UK', [['MUG', 4], ['BAG', 1]]));
+    expect(free.subtotal).toBe(4000);
+    expect(free.shipping).toBe(0);
+
+    const paid = totals(cart('UK', [['MUG', 4], ['BAG', 1]], 'SAVE10'));
+    expect(paid.shipping).toBe(700);
+  });
+});
+
+describe('shipping threshold uses the discounted subtotal', () => {
+  test('US order above the threshold pays shipping after a coupon', () => {
+    const t = totals(cart('US', [['BAG', 2], ['MUG', 2]], 'FLAT5'));
+    expect(t.subtotal).toBe(5300);
+    expect(t.coupon).toBe(500);
+    expect(t.shipping).toBe(800);
+  });
+
+  test('US order without a coupon ships free', () => {
+    expect(totals(cart('US', [['BAG', 2], ['MUG', 2]])).shipping).toBe(0);
+  });
+});
+
+describe('same-sku lines are merged before pricing', () => {
+  test('two lines of 5 mugs reach the 10 unit tier as one line', () => {
+    const t = totals(cart('US', [['MUG', 5], ['MUG', 5]]));
+    expect(t.lines).toHaveLength(1);
+    expect(t.lines[0]!.quantity).toBe(10);
+    expect(t.lines[0]!.subtotal).toBe(4500);
+    expect(t.lines[0]!.discount).toBe(225);
+    expect(t.subtotal).toBe(4275);
+  });
+
+  test('two lines of 25 mugs reach the 50 unit tier', () => {
+    const t = totals(cart('US', [['MUG', 25], ['MUG', 25]]));
+    expect(t.lines).toHaveLength(1);
+    expect(t.lines[0]!.discount).toBe(2250);
+    expect(t.subtotal).toBe(20250);
+  });
+});
+
+describe('rounding and totals', () => {
+  test('tax rounds half up to the cent', () => {
+    expect(taxFor(REGIONS.US, 50)).toBe(4);
+    expect(taxFor(REGIONS.US, 51)).toBe(4);
+  });
+
+  test('total is discounted subtotal + shipping + tax', () => {
+    const t = totals(cart('EU', [['TEE', 2]], 'SAVE10'));
+    expect(t.subtotal).toBe(3000);
+    expect(t.coupon).toBe(300);
+    expect(t.shipping).toBe(900);
+    expect(t.tax).toBe(720);
+    expect(t.total).toBe(t.subtotal - t.coupon + t.shipping + t.tax);
+    expect(t.total).toBe(4320);
+  });
+
+  test('FLAT5 never takes the order below zero', () => {
+    const t = totals(cart('US', [['PEN', 1]], 'FLAT5'));
+    expect(t.coupon).toBe(120);
+    expect(t.total).toBe(t.subtotal - t.coupon + t.shipping + t.tax);
+  });
+});

