+
+// Expected values worked by hand from the rules in README.md.
+describe('pricing rules', () => {
+  test('bulk tiers start at 10 and 50 units', () => {
+    // 9 pens = 1080, no discount; shipping 800; tax 7% of 1880 = 131.6 -> 132
+    expect(totals(cart('US', [['PEN', 9]]))).toMatchObject({ subtotal: 1080, shipping: 800, tax: 132, total: 2012 });
+    // 10 mugs = 4500, 5% off = 225; shipping 800; tax 7% of 5075 = 355.25 -> 355
+    expect(totals(cart('US', [['MUG', 10]]))).toMatchObject({ subtotal: 4275, shipping: 800, tax: 355, total: 5430 });
+    // 50 pens = 6000, 10% (not 5%) off = 600; free shipping; tax 7% of 5400 = 378
+    expect(totals(cart('US', [['PEN', 50]]))).toMatchObject({ subtotal: 5400, shipping: 0, tax: 378, total: 5778 });
+  });
+
+  test('lines of the same sku are merged before bulk discounts', () => {
+    // 6 + 4 mugs is 10 units, so the 5% tier applies: 4500 - 225
+    const t = totals(cart('US', [['MUG', 6], ['MUG', 4]]));
+    expect(t.lines).toHaveLength(1);
+    expect(t).toMatchObject({ subtotal: 4275, shipping: 800, tax: 355, total: 5430 });
+  });
+
+  test('free shipping is judged after the coupon', () => {
+    // 12 mugs = 5400, bulk -270 -> 5130, FLAT5 -> 4630 < 5000, so shipping is charged
+    expect(totals(cart('US', [['MUG', 12]], 'FLAT5'))).toMatchObject({ subtotal: 5130, coupon: 500, shipping: 800, tax: 380, total: 5810 });
+    // without the coupon 5130 >= 5000 ships free
+    expect(totals(cart('US', [['MUG', 12]]))).toMatchObject({ subtotal: 5130, coupon: 0, shipping: 0, tax: 359, total: 5489 });
+  });
+
+  test('UK free shipping starts at 4000', () => {
+    // 2200 + 1200 + 5 * 120 = 4000 exactly; tax 20% of 4000 = 800
+    expect(totals(cart('UK', [['BAG', 1], ['CAP', 1], ['PEN', 5]]))).toMatchObject({ subtotal: 4000, shipping: 0, tax: 800, total: 4800 });
+  });
+
+  test('FLAT5 never takes the order below zero', () => {
+    // 1 mug = 450, FLAT5 takes 450 (not 500); shipping 800; tax 7% of 800 = 56
+    expect(totals(cart('US', [['MUG', 1]], 'FLAT5'))).toMatchObject({ subtotal: 450, coupon: 450, shipping: 800, tax: 56, total: 856 });
