+import { expect, test } from 'bun:test';
+import { LRU } from '../src/lru.ts';
+
+test('get promotes and capacity evicts the least recently used', () => {
+  const events: [string, number, string][] = [];
+  const cache = new LRU<string, number>(2, 10_000, () => 0);
+  cache.onEvict = (key, value, reason) => events.push([key, value, reason]);
+  cache.set('a', 1);
+  cache.set('b', 2);
+  expect(cache.get('a')).toBe(1);
+  cache.set('c', 3);
+  expect(cache.get('b')).toBeUndefined();
+  expect(cache.keys()).toEqual(['c', 'a']);
+  expect(events).toEqual([['b', 2, 'capacity']]);
+});
+
+test('expired entries are dropped when found', () => {
+  let t = 0;
+  const events: [string, number, string][] = [];
+  const cache = new LRU<string, number>(3, 1000, () => t);
+  cache.onEvict = (key, value, reason) => events.push([key, value, reason]);
+  cache.set('a', 1);
+  t = 999;
+  expect(cache.get('a')).toBe(1);
+  t = 1000;
+  expect(cache.get('a')).toBeUndefined();
+  expect(events).toEqual([['a', 1, 'expired']]);
+  expect(cache.keys()).toEqual([]);
+});
+
+test('set refreshes the ttl and evicts expired entries before live ones', () => {
+  let t = 0;
+  const events: [string, number, string][] = [];
+  const cache = new LRU<string, number>(2, 1000, () => t);
+  cache.onEvict = (key, value, reason) => events.push([key, value, reason]);
+  cache.set('a', 1);
+  t = 500;
+  cache.set('b', 2);
+  t = 600;
+  expect(cache.get('b')).toBe(2); // b was stored at 500, so it expires at 1500
+  t = 1000;
+  cache.set('c', 3); // a expired at 1000, the cache holds a, b, c
+  expect(events).toEqual([['a', 1, 'expired']]);
+  expect(cache.keys()).toEqual(['c', 'b']);
+});
+
+test('delete reports live removals and drops expired ones', () => {
+  let t = 0;
+  const events: [string, number, string][] = [];
+  const cache = new LRU<string, number>(3, 1000, () => t);
+  cache.onEvict = (key, value, reason) => events.push([key, value, reason]);
+  cache.set('a', 1);
+  cache.set('b', 2);
+  expect(cache.delete('a')).toBe(true);
+  expect(cache.delete('a')).toBe(false);
+  t = 1000;
+  expect(cache.delete('b')).toBe(false);
+  expect(events).toEqual([
+    ['a', 1, 'delete'],
+    ['b', 2, 'expired'],
+  ]);
+});
+
+test('size and keys only count live entries, most recently used first', () => {
+  let t = 0;
+  const cache = new LRU<string, number>(3, 1000, () => t);
+  cache.set('a', 1);
+  t = 200;
+  cache.set('b', 2);
+  t = 400;
+  cache.get('a');
+  expect(cache.keys()).toEqual(['a', 'b']);
+  expect(cache.size).toBe(2);
+  t = 1000; // a expired at 1000, b at 1200
