+import { expect, test } from 'bun:test';
+import { slugify, uniqueSlug } from '../src/slug.ts';
+
+test('slugify removes diacritics and expands special letters', () => {
+  expect(slugify('Đà Nẵng')).toBe('da-nang');
+  expect(slugify('Straße')).toBe('strasse');
+  expect(slugify('Æther')).toBe('aether');
+  expect(slugify('Œuvre')).toBe('oeuvre');
+  expect(slugify('Smørrebrød')).toBe('smorrebrod');
+  expect(slugify('Łódź')).toBe('lodz');
+  expect(slugify('źółć')).toBe('zolc');
+});
+
+test('slugify collapses separators and trims them', () => {
+  expect(slugify('  --Hello,  World!--  ')).toBe('hello-world');
+  expect(slugify('a_b/c')).toBe('a-b-c');
+  expect(slugify('UPPER case 123')).toBe('upper-case-123');
+  expect(slugify('!!!')).toBe('');
+});
+
+test('slugify max cuts at a dash or at max', () => {
+  expect(slugify('ab-cd-ef', 5)).toBe('ab-cd');
+  expect(slugify('ab-cd-ef', 4)).toBe('ab');
+  expect(slugify('abcdef-gh', 5)).toBe('abcde');
+  expect(slugify('abcdef', 3)).toBe('abc');
+  expect(slugify('ab-cd', 10)).toBe('ab-cd');
+  expect(slugify('ab-cd', 2)).toBe('ab');
+});
+
+test('uniqueSlug finds the first free suffix', () => {
+  expect(uniqueSlug('post', new Set())).toBe('post');
+  expect(uniqueSlug('post', new Set(['post', 'post-2']))).toBe('post-3');
+  expect(uniqueSlug('post', new Set(['post', 'post-3']))).toBe('post-2');
+});

