+  expect(parseDuration('250ms')).toBe(250);
+  expect(parseDuration('1.5h')).toBe(5_400_000);
+  expect(parseDuration('5h30m15s')).toBe(19_815_000);
+  expect(parseDuration('0.5s')).toBe(500);
+});
+
+test('duration rejects anything that is not number-unit parts', () => {
+  for (const bad of ['', '   ', '10', 'h', 'ms', '-1s', '1h 30', '1 h']) {
+    expect(() => parseDuration(bad)).toThrow(`"${bad}"`);
+  }
+});
+
+test('duration formats the shortest text from the largest unit', () => {
+  expect(formatDuration(0)).toBe('0s');
+  expect(formatDuration(1_500)).toBe('1s500ms');
+  expect(formatDuration(86_400_000)).toBe('1d');
+  expect(formatDuration(90_000)).toBe('1m30s');
+  expect(formatDuration(500)).toBe('500ms');
+  expect(formatDuration(90_061_001)).toBe('1d1h1m1s1ms');
+  expect(() => formatDuration(-1)).toThrow();
+});
+
+test('slug strips diacritics and expands special letters', () => {
+  expect(slugify('à ç ñ ź')).toBe('a-c-n-z');
+  expect(slugify('Straße')).toBe('strasse');
+  expect(slugify('Æther Œuvre')).toBe('aether-oeuvre');
+  expect(slugify('smørrebrød')).toBe('smorrebrod');
+  expect(slugify('Łódź')).toBe('lodz');
+  expect(slugify('Đà Nẵng')).toBe('da-nang');
+});
+
+test('slug separates on anything that is not a-z or 0-9', () => {
+  expect(slugify('  --Hello__World!! ')).toBe('hello-world');
+  expect(slugify('Hello 123 World')).toBe('hello-123-world');
+  expect(slugify('!!!')).toBe('');
+});
+
+test('slug cuts at max without a dangling dash', () => {
+  expect(slugify('ab-cd-ef', 5)).toBe('ab-cd');
+  expect(slugify('abcdefgh', 3)).toBe('abc');
+  expect(slugify('hello-world', 6)).toBe('hello');
+  expect(slugify('hello', 10)).toBe('hello');
+});
+
+test('uniqueSlug finds the first free suffix', () => {
+  expect(uniqueSlug('post', new Set())).toBe('post');
+  expect(uniqueSlug('post', new Set(['post', 'post-2']))).toBe('post-3');
+  expect(uniqueSlug('post', new Set(['post', 'post-3']))).toBe('post-2');
+});
