+test('lru reports evictions and moves hits to the front', () => {
+  let t = 0;
+  const evicted: [string, number, string][] = [];
+  const cache = new LRU<string, number>(2, 100, () => t);
+  cache.onEvict = (key, value, reason) => evicted.push([key, value, reason]);
+
+  cache.set('a', 1);
+  cache.set('b', 2);
+  expect(cache.get('a')).toBe(1);
+  cache.set('c', 3);
+  expect(evicted).toEqual([['b', 2, 'capacity']]);
+  expect(cache.keys()).toEqual(['c', 'a']);
+
+  t = 100;
+  expect(cache.get('a')).toBeUndefined();
+  expect(evicted).toEqual([['b', 2, 'capacity'], ['a', 1, 'expired']]);
+});
+
+test('lru removes expired entries before live ones', () => {
+  let t = 0;
+  const evicted: [string, string][] = [];
+  const cache = new LRU<string, number>(2, 100, () => t);
+  cache.onEvict = (key, _value, reason) => evicted.push([key, reason]);
+
+  cache.set('a', 1);
+  t = 100;
+  cache.set('b', 2);
+  cache.set('c', 3);
+  expect(evicted).toEqual([['a', 'expired']]);
+  expect(cache.keys()).toEqual(['c', 'b']);
+});
+
+test('lru delete distinguishes live from expired entries', () => {
+  let t = 0;
+  const evicted: [string, number, string][] = [];
+  const cache = new LRU<string, number>(2, 100, () => t);
+  cache.onEvict = (key, value, reason) => evicted.push([key, value, reason]);
+
+  cache.set('a', 1);
+  expect(cache.delete('a')).toBe(true);
+  expect(cache.delete('a')).toBe(false);
+  expect(evicted).toEqual([['a', 1, 'delete']]);
+
+  cache.set('b', 2);
+  t = 100;
+  expect(cache.delete('b')).toBe(false);
+  expect(evicted).toEqual([['a', 1, 'delete'], ['b', 2, 'expired']]);
+});
+
+test('lru size and keys count only live entries', () => {
+  let t = 0;
+  const evicted: string[] = [];
+  const cache = new LRU<string, number>(3, 100, () => t);
+  cache.onEvict = (key) => evicted.push(key);
+
+  cache.set('a', 1);
+  cache.set('b', 2);
+  expect(cache.size).toBe(2);
+  expect(cache.keys()).toEqual(['b', 'a']);
+
+  t = 100;
+  expect(cache.size).toBe(0);
+  expect(cache.keys()).toEqual([]);
+  expect(evicted).toEqual([]);
+});
+
+test('lru setting an existing key refreshes its ttl and recency', () => {
+  let t = 0;
+  const cache = new LRU<string, number>(2, 100, () => t);
+  cache.set('a', 1);
+  cache.set('b', 2);
+
+  t = 50;
+  cache.set('a', 10);
+  expect(cache.keys()).toEqual(['a', 'b']);
+
+  t = 100;
+  expect(cache.get('a')).toBe(10);
+  t = 150;
+  expect(cache.get('a')).toBeUndefined();
+});
